package com.bank.ranking;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class RankingDao {
    private static final Logger log = Logger.getLogger(RankingDao.class.getName());
    private final Connection conn;

    public RankingDao(Connection conn) { this.conn = conn; }

    // Show ROW_NUMBER, RANK, DENSE_RANK together so ties are visible.
    public List<String> compareRankings() throws Exception {
        String sql =
            "SELECT account_id, total, " +
            "ROW_NUMBER() OVER (ORDER BY total DESC) AS rn, " +
            "RANK()       OVER (ORDER BY total DESC) AS rnk, " +
            "DENSE_RANK() OVER (ORDER BY total DESC) AS drnk " +
            "FROM account_spend ORDER BY total DESC";
        List<String> rows = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                String line = rs.getString("account_id") + " total=" + rs.getBigDecimal("total")
                    + " rn=" + rs.getInt("rn") + " rank=" + rs.getInt("rnk")
                    + " dense=" + rs.getInt("drnk");
                rows.add(line);
                log.info(line);
            }
        }
        return rows;
    }

    // Classic top-1-per-group using ROW_NUMBER (unique pick even on ties).
    public List<String> latestPerAccount() throws Exception {
        String sql =
            "SELECT account_id, month, total FROM (" +
            "  SELECT account_id, month, total, " +
            "  ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY month DESC) AS rn " +
            "  FROM account_spend) t WHERE rn = 1";
        List<String> rows = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {
            while (rs.next()) rows.add(rs.getString("account_id") + " latest month " + rs.getInt("month"));
        }
        log.info(() -> "Latest per account: " + rows);
        return rows;
    }
}
