package com.bank.ranking;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.logging.Logger;

public class RankingDemo {
    private static final Logger log = Logger.getLogger(RankingDemo.class.getName());

    public static void main(String[] args) throws Exception {
        try (Connection conn = DriverManager.getConnection(
                "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret")) {
            RankingDao dao = new RankingDao(conn);
            dao.compareRankings();   // see ties: ROW_NUMBER unique, RANK gaps, DENSE_RANK no gaps
            dao.latestPerAccount();  // top-1-per-group with ROW_NUMBER
            log.info("ROW_NUMBER=unique; RANK=ties+gaps; DENSE_RANK=ties+no gaps.");
        }
    }
}
